action.code:
# Let's examine character by character
examples_to_analyze = [
    (2, 'vvy', 'vvzdwaj'),
    (3, 'fkek', 'fkadk'), 
    (4, 'ee', 'adad')
]

for idx, inp, out in examples_to_analyze:
    print(f"Example {idx}: '{inp}' -> '{out}'")

    # Find differences position by position
    min_len = min(len(inp), len(out))
    for i in range(min_len):
        if inp[i] != out[i]:
            print(f"  Position {i}: '{inp[i]}' -> '{out[i]}'")

    # Show what's extra in output
    if len(out) > len(inp):
        print(f"  Extra chars in output: '{out[len(inp):]}'")
    elif len(inp) > len(out):
        print(f"  Extra chars in input: '{inp[len(out):]}'")
    print()

